data.nginx.conf:
pid /tmp/nginx.pid;
error_log /dev/stderr warn;
worker_processes 1;
events { worker_connections 128; }
http {
 access_log off;
 client_max_body_size 2m;
 client_body_temp_path /tmp/client_temp;
 proxy_temp_path /tmp/proxy_temp;
 fastcgi_temp_path /tmp/fastcgi_temp;
 uwsgi_temp_path /tmp/uwsgi_temp;
 scgi_temp_path /tmp/scgi_temp;
 proxy_connect_timeout 3s;
 proxy_read_timeout 10s;
 server {
  listen 8080;
  location = /ready { proxy_pass http://127.0.0.1:9090/-/ready; }
  location ~ ^(/api/v1/(query|query_range|alerts|rules|targets|labels|label/[a-zA-Z_][a-zA-Z0-9_]*/values|status/buildinfo)|/metrics)$ {
   if ($request_method != GET) { return 405; }
   auth_basic "Aegis telemetry";
   auth_basic_user_file /run/telemetry-auth/query.htpasswd;
   proxy_pass http://127.0.0.1:9090;
  }
  location / { return 404; }
 }
}

data.rules.json:
{
  "groups": [
    {
      "name": "aegis-applications",
      "interval": "15s",
      "rules": [
        {
          "alert": "AegisHighErrorRate",
          "expr": "sum by (k8s_namespace_name, aegis_cluster_uid) (rate(http_server_requests_total{k8s_namespace_name=~\"aegis-.*\",http_response_status_code=~\"5..\"}[1m])) / clamp_min(sum by (k8s_namespace_name, aegis_cluster_uid) (rate(http_server_requests_total{k8s_namespace_name=~\"aegis-.*\"}[1m])), 0.001) > 0.05",
          "for": "30s",
          "labels": {
            "severity": "warning"
          },
          "annotations": {
            "summary": "Application HTTP errors exceed 5%",
            "grafana_url": "http://127.0.0.1:3000/d/aegis-application?var-cluster={{ $labels.aegis_cluster_uid }}&var-namespace={{ $labels.k8s_namespace_name }}"
          }
        },
        {
          "alert": "AegisPodNotReady",
          "expr": "k8s_pod_condition_ready{k8s_namespace_name=~\"aegis-.*\"} == 0",
          "for": "2m",
          "labels": {
            "severity": "warning"
          },
          "annotations": {
            "summary": "Application pod is not ready",
            "grafana_url": "http://127.0.0.1:3000/d/aegis-application?var-cluster={{ $labels.aegis_cluster_uid }}&var-namespace={{ $labels.k8s_namespace_name }}"
          }
        },
        {
          "alert": "AegisTelemetryScrapeUnavailable",
          "expr": "up{job=\"aegis-telemetry\"} == 0",
          "for": "1m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "Telemetry collection is unavailable",
            "grafana_url": "http://127.0.0.1:3000/d/aegis-platform?var-cluster={{ $labels.aegis_cluster_uid }}"
          }
        },
        {
          "alert": "AegisApplicationUnavailable",
          "expr": "k8s_deployment_available{k8s_namespace_name=~\"aegis-.*\"} == 0",
          "for": "2m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "Application deployment has no available replicas",
            "grafana_url": "http://127.0.0.1:3000/d/aegis-application?var-cluster={{ $labels.aegis_cluster_uid }}&var-namespace={{ $labels.k8s_namespace_name }}"
          }
        },
        {
          "alert": "AegisPodCrashLoop",
          "expr": "k8s_container_status_reason{k8s_namespace_name=~\"aegis-.*\",k8s_container_status_reason=\"CrashLoopBackOff\"} > 0",
          "for": "2m",
          "labels": {
            "severity": "warning"
          },
          "annotations": {
            "summary": "Application container is in CrashLoopBackOff",
            "grafana_url": "http://127.0.0.1:3000/d/aegis-application?var-cluster={{ $labels.aegis_cluster_uid }}&var-namespace={{ $labels.k8s_namespace_name }}"
          }
        },
        {
          "alert": "AegisExcessiveRestarts",
          "expr": "k8s_container_restarts{k8s_namespace_name=~\"aegis-.*\"} > 5",
          "for": "2m",
          "labels": {
            "severity": "warning"
          },
          "annotations": {
            "summary": "Application container reports more than five recent restarts",
            "grafana_url": "http://127.0.0.1:3000/d/aegis-application?var-cluster={{ $labels.aegis_cluster_uid }}&var-namespace={{ $labels.k8s_namespace_name }}"
          }
        },
        {
          "alert": "AegisHighLatency",
          "expr": "histogram_quantile(0.95, sum by (le, k8s_namespace_name, aegis_cluster_uid) (rate(http_server_request_duration_seconds_bucket{k8s_namespace_name=~\"aegis-.*\"}[5m]))) > 1 and on(k8s_namespace_name, aegis_cluster_uid) sum by (k8s_namespace_name, aegis_cluster_uid) (rate(http_server_requests_total{k8s_namespace_name=~\"aegis-.*\"}[5m])) > 1",
          "for": "5m",
          "labels": {
            "severity": "warning"
          },
          "annotations": {
            "summary": "Application p95 latency exceeds one second with sustained traffic",
            "grafana_url": "http://127.0.0.1:3000/d/aegis-application?var-cluster={{ $labels.aegis_cluster_uid }}&var-namespace={{ $labels.k8s_namespace_name }}"
          }
        },
        {
          "alert": "AegisNodePressure",
          "expr": "(k8s_node_condition_memory_pressure == 1) or (k8s_node_condition_disk_pressure == 1)",
          "for": "2m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "Kubernetes node has memory or disk pressure",
            "grafana_url": "http://127.0.0.1:3000/d/aegis-platform?var-cluster={{ $labels.aegis_cluster_uid }}"
          }
        },
        {
          "alert": "AegisCollectorUnavailable",
          "expr": "up{job=\"aegis-collector-internal\"} == 0",
          "for": "1m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "Collector internal metrics are unavailable",
            "grafana_url": "http://127.0.0.1:3000/d/aegis-platform?var-cluster={{ $labels.aegis_cluster_uid }}"
          }
        },
        {
          "alert": "AegisMonitoringBackendUnavailable",
          "expr": "up{job=\"aegis-monitoring-backends\"} == 0",
          "for": "1m",
          "labels": {
            "severity": "critical"
          },
          "annotations": {
            "summary": "Monitoring backend scrape is unavailable",
            "grafana_url": "http://127.0.0.1:3000/d/aegis-platform?var-cluster={{ $labels.aegis_cluster_uid }}"
          }
        }
      ]
    }
  ]
}
